solution.exercise.c:
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
int degree_of_separation(const family*f,size_t n,const char*a,const char*b){size_t cap=n;for(size_t i=0;i<n;i++)cap+=f[i].count;const char**names=(const char**)malloc(cap*sizeof(char*));size_t count=0;for(size_t i=0;i<n;i++){for(size_t j=0;j<=f[i].count;j++){const char*s=j?f[i].children[j-1]:f[i].parent;size_t k=0;while(k<count&&strcmp(names[k],s))k++;if(k==count)names[count++]=s;}}int ai=-1,bi=-1;for(size_t i=0;i<count;i++){if(!strcmp(names[i],a))ai=(int)i;if(!strcmp(names[i],b))bi=(int)i;}if(ai<0||bi<0){free(names);return ai<0?-2:-3;}bool*edges=(bool*)calloc(count*count,sizeof(bool));for(size_t i=0;i<n;i++)for(size_t x=0;x<=f[i].count;x++)for(size_t y=x+1;y<=f[i].count;y++){const char*s=x?f[i].children[x-1]:f[i].parent,*t=f[i].children[y-1];size_t u=0,v=0;while(strcmp(names[u],s))u++;while(strcmp(names[v],t))v++;edges[u*count+v]=edges[v*count+u]=true;}int*d=(int*)malloc(count*sizeof(int));size_t*q=(size_t*)malloc(count*sizeof(size_t));for(size_t i=0;i<count;i++)d[i]=-1;size_t head=0,tail=0;q[tail++]=(size_t)ai;d[ai]=0;while(head<tail){size_t u=q[head++];for(size_t v=0;v<count;v++)if(edges[u*count+v]&&d[v]<0){d[v]=d[u]+1;q[tail++]=v;}}int result=d[bi];free(names);free(edges);free(d);free(q);return result;}

