int main(void){
const char*c[]={"Isla","Tariq"},*d[]={"Uma"},*e[]={"Kevin"};family f[]={{"Helena",c,2},{"Isla",d,1},{"Erdos",e,1}};assert(degree_of_separation(f,3,"Tariq","Uma")==2);assert(degree_of_separation(f,3,"Isla","Tariq")==1);assert(degree_of_separation(f,3,"Isla","Kevin")==-1);assert(degree_of_separation(f,3,"Missing","Uma")==-2);assert(degree_of_separation(f,3,"Uma","Missing")==-3);

